INSERT INTO `creature_text` (`entry`,`groupid`,`id`,`text`,`type`,`language`,`probability`,`emote`,`duration`,`sound`,`comment`) VALUES
(61243,0,0,'I hear something...',14,0,0.0,0,0,32495,'Gekkan intro'),
(61243,1,0,'Search his corpse!',14,0,0.0,0,0,32496,'Gekkan kill target'),
(61243,2,0,'Slay them!',14,0,0.0,0,0,32497,'Gekkan spell cast'),
(61243,3,0,'Stop them!',14,0,0.0,0,0,32488,'Gekkan aggro'),
(61243,4,0,'Such a waste...',14,0,0.0,0,0,32494,'Gekkan death'),
(61398,0,0,'What is this, more have come to claim my crown? They are small and weak.',14,0,100.0,0,0,28355,'Xin the Weaponmaster - TALK_INTRO'),
(61398,1,0,'You are not the first to challenge me, peons. You will not be the last.',14,0,100.0,0,0,28349,'Xin the Weaponmaster - TALK_AGGRO'),
(61398,2,0,'Face the might of my arsenal, weaklings!',14,0,100.0,0,0,28350,'Xin the Weaponmaster - TALK_AXES'),
(61398,3,0,'%s activates his |cFFFF0404|Hspell:119374|h[Whirlwinding Axe]|h|r trap!',41,0,100.0,0,0,28350,'Xin the Weaponmaster - EMOTE_AXES'),
(61398,4,0,'%s activates his |cFFFF0404|Hspell:119311|h[Stream of Blades]|h|r trap!',41,0,100.0,0,0,0,'Xin the Weaponmaster - EMOTE_BLADES'),
(61398,5,0,'MY MIGHT IS ENDLESS!',14,0,100.0,0,0,28351,'Xin the Weaponmaster - TALK_BLADES'),
(61398,6,0,'ENOUGH OF THIS FARCE! You will feel PAIN, cowards!',14,0,100.0,0,0,28360,'Xin the Weaponmaster - TALK_CROSSBOW'),
(61398,7,0,'%s activates his |cFFFF0404|Hspell:120142|h[Crossbow]|h|r trap!',41,0,100.0,0,0,28360,'Xin the Weaponmaster - EMOTE_CROSSBOW'),
(61398,8,0,'You call that... a fight...?',14,0,100.0,0,0,28352,'Xin the Weaponmaster to Player - TALK_DEATH'),
(61398,9,0,'%s spits blood in your face.',16,0,100.0,0,0,0,'Xin the Weaponmaster to Player - EMOTE_DEATH'),
(61398,10,0,'See how effortlessly I CRUSH your bones!',14,0,50.0,0,0,28357,'Xin slay 1 - TALK_SLAY'),
(61398,10,1,'Fall to your knees, coward!',14,0,50.0,0,0,28358,'Xin slay 2 - TALK_SLAY'),
(61398,11,0,'I. Am. UNDEFEATED!',14,0,100.0,0,0,28356,'Xin reset - TALK_RESET'),
(61442,0,0,'Clan Gurthan will show our King and the rest of you power-hungry imposters why we are the rightful ones at his side!',14,0,0.0,0,0,27932,'Kuai the Brute intro'),
(61442,1,0,'We will never surrender our right to rule the destiny of our people!',14,0,0.0,0,0,27933,'Kuai retire'),
(61442,2,0,'The glory of Gurthan!',14,0,0.0,0,0,27942,'Kuai kill target'),
(61442,3,0,'Who allowed these outsiders inside our halls? Only Clan Harthak or Clan Kargesh would stoop to such treachery!',14,0,0.0,0,0,27940,'Kuai postcombat #1'),
(61442,4,0,'A well-scripted exchange; but we are not fooled. Your clans are clearly in league with one another. For the glory of our king, our empire, we will put you all down!',14,0,0.0,0,0,27941,'Kuai postcombat #2'),
(61442,5,0,'We are the greatest!',14,0,50.0,0,0,27934,'Kuai idle #1'),
(61442,5,1,'These other clans are nothing!',14,0,50.0,0,0,27935,'Kuai idle #2'),
(61444,0,0,'Clan Harthak will show all why they are the truest of Mogu!',14,0,0.0,0,0,27947,'Ming the Cunning intro'),
(61444,1,0,'Our clan is the true clan! No interloper can change that!',14,0,0.0,0,0,27948,'Ming retire'),
(61444,2,0,'This is the might of Harthak!',14,0,0.0,0,0,27957,'Ming kill target'),
(61444,3,0,'Only the dogs of Clan Gurthan would point fingers at others for their own failures! Your clan is the most desperate. It must\'ve been you!',14,0,0.0,0,0,27955,'Ming postcombat #1'),
(61444,4,0,'Our clan holds true to the ways set forth by the ancients. We deserve the king\'s favor above all others!',14,0,50.0,0,0,27950,'Ming idle #1'),
(61444,4,1,'These other clans aren\'t worthy of your time, great king!',14,0,50.0,0,0,27949,'Ming idle #2'),
(61445,0,0,'Clan Kargesh will demonstrate why only the strong deserve to stand at our King\'s side!',14,0,0.0,0,0,28246,'Haiyan the Unstoppable intro'),
(61445,1,0,'Impossible! Our might is the greatest in all the empire!',14,0,0.0,0,0,28247,'Haiyan retire'),
(61445,2,0,'For Kargesh!',14,0,0.0,0,0,28256,'Haiyan kill target'),
(61445,3,0,'Clan Gurthan is right! Only the honorless Clan Harthak could bring in a lesser race to do their bidding. You must be traitors!',14,0,0.0,0,0,28254,'Haiyan postcombat #1'),
(61445,4,0,'The Mogu cannot reclaim our rightful glory without our clan\'s strength!',14,0,50.0,0,0,28248,'Haiyan idle #1'),
(61445,4,1,'These pathetic clans are beneath you, my king. They sully the great legacy of our people!',14,0,50.0,0,0,28249,'Haiyan idle #2'),
(61884,0,0,'Useless, all of you! Even the guards you give me in tribute can\'t keep these lesser beings from my palace.',14,0,0.0,15,0,28353,'Trial of the King intro #1'),
(61884,1,0,'Redeem, nay, PROVE yourselves now. Deal with these intruders. The clan who brings me their heads will have my favor!',14,0,0.0,14,0,28354,'Trial of the King intro #2');
